private void permuteRecursive(int[] nums, List<Integer> current, List<List<Integer>> result) {
        // If the current permutation is complete, add it to the result
        if (current.size() == nums.length) {
            result.add(current);
            return;
        }
        // Generate permutations by including each number as the current element
        for (int i = 0; i < nums.length; i++) {
            if (!current.contains(nums[i])) {
                // Include the number in the current permutation
                List<Integer> newCurrent = new ArrayList<>(current);
                newCurrent.add(nums[i]);
                // Recursively generate permutations for the remaining elements
                permuteRecursive(nums, newCurrent, result);
            }
        }
    }

