public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate the input parameters
    if (n <= 0 || start == null || end == null || paths == null || start.length != 2 || end.length != 2 || paths.length == 0) {
        return "Invalid input parameters";
    }

    // Create a boolean matrix to mark visited nodes and a set of all nodes
    boolean[][] visited = new boolean[n][n];
    Set<Integer> allNodes = new HashSet<>();
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            visited[i][j] = false;
            allNodes.add(i * 100 + j); // Assuming coordinates are represented by integers
        }
    }

    // Add the starting node to the visited set and add to findAllNodes
    visited[start[0]][start[1]] = true;
    allNodes.add(start[0] * 100 + start[1]);

    // Queue to perform breadth-first search
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(start[0] * 100 + start[1]);

    // Explore the maze using BFS
    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == end[0] * 100 + end[1]) {
            return "can be travelled"; // Travel is possible
        }

        // Check adjacent nodes
        for (int[] dir : new int[][] {{-1, 0}, {1, 0}, {0, -1}, {0, 1}}) {
            int x = current / 100 + dir[0];
            int y = current % 100 + dir[1];
            if (x >= 0 && x < n && y >= 0 && y < n && !visited[x][y]) {
                visited[x][y] = true;
                allNodes.add(x * 100 + y);
                queue.offer(x * 100 + y);
            }
        }
    }

    return "cannot be travelled"; // Travel is not possible
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a boolean array to keep track of visited cells
    boolean[][] visited = new boolean[n][n];

    // Mark the starting cell as visited
    visited[start[0]][start[1]] = true;

    // Use Breadth-First Search to traverse the maze
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int row = current[0];
        int col = current[1];

        // Continue if the current cell is the end cell
        if (row == end[0] && col == end[1]) {
            return "can be travelled";
        }

        // Explore all four adjacent cells
        if (row > 0 && !visited[row - 1][col]) {
            visited[row - 1][col] = true;
            queue.add(new int[]{row - 1, col});
        }
        if (row < n - 1 && !visited[row + 1][col]) {
            visited[row + 1][col] = true;
            queue.add(new int[]{row + 1, col});
        }
        if (col > 0 && !visited[row][col - 1]) {
            visited[row][col - 1] = true;
            queue.add(new int[]{row, col - 1});
        }
        if (col < n - 1 && !visited[row][col + 1]) {
            visited[row][col + 1] = true;
            queue.add(new int[]{row, col + 1});
        }
    }

    // If no valid path is found, return "cannot be travelled"
    return "cannot be travelled";
}

