private static boolean canTravelMaze(int x, int y, int endX, int endY, int[][] visited) {
    if (visited[x][y] == 1) {
        return false;
    } else if (x == endX && y == endY) {
        return true;
    } else {
        visited[x][y] = 1;

        for (int[] path : paths) {
            int neighborX = x + path[0];
            int neighborY = y + path[1];
            if (neighborX >= 0 && neighborX < n && neighborY >= 0 && neighborY < n && !visited[neighborX][neighborY]) {
                if (canTravelMaze(neighborX, neighborY, endX, endY, visited)) {
                    return true;
                }
            }
        }

        return false;
    }
}

