public static String appx(String word1, String word2) {
    int commonLetters = 0;
    for (int i = 0; i < word1.length() && i < word2.length(); i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            commonLetters++;
        }
    }

    int totalLetters = word1.length() + word2.length();
    double approximateValue = (double) commonLetters / totalLetters;

    // Convert to reduced fraction
    int denominator = totalLetters;
    int numerator = commonLetters;

    // Find the greatest common divisor
    int gcd = gcd(numerator, denominator);

    // Simplify the fraction
    numerator /= gcd;
    denominator /= gcd;

    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

private static int gcd(int a, int b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}

