public double trimMean(int[] arr) {
    PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
    PriorityQueue<Integer> minHeap = new PriorityQueue<>();

    for (int num : arr) {
        if (maxHeap.size() < 5) {
            maxHeap.add(num);
        } else if (minHeap.size() < 5) {
            minHeap.add(num);
        } else {
            if (maxHeap.peek() > minHeap.peek()) {
                maxHeap.poll();
                maxHeap.add(num);
            } else {
                minHeap.poll();
                minHeap.add(num);
            }
        }
    }

    double sum = 0;
    for (int i = 0; i < 20; i++) {
        if (!maxHeap.isEmpty()) {
            sum += maxHeap.poll();
        }
        if (!minHeap.isEmpty()) {
            sum += minHeap.poll();
        }
    }

    return sum / 20.0;
}

public static double trimMean(int[] arr) {
