        if (length <= 2) {
            return 0.0;
        }

        Arrays.sort(arr);
        int start = (int) (length * 0.05);
        int end = length - start - 1;

        int sum = 0;
        for (int i = start; i <= end; i++) {
            sum += arr[i];
        }

        return (double) sum / (length - 2 * (int) (length * 0.05));
    }

