public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    int pairs = n / 2;
    int freq[] = new int[k];

    for (int i : arr) {
        int modulus = i % k;
        freq[modulus]++;
    }

    int oddCount = 0;
    for (int i = 1; i < k; i += 2) {
        if (freq[i] % 2 != 0) {
            oddCount++;
        }
        if (i != (k - i)) {
            if (freq[i] != freq[k - i]) {
                return false;
            }
        }
    }

    if (oddCount <= 1) {
        return true;
    }

    return false;
}

public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) {
        return false; // If there is an odd number of elements, it is not possible to pair them
    }

    int[] counts = new int[k];
    for (int num : arr) {
        counts[num % k]++;
    }

    // If the counts of elements with remainders not exceeding k/2 and the number of elements with remainder k/2 are even, it is possible
    int oddCount = 0;
    for (int i = 1; i <= k / 2; i++) {
        if (counts[i] % 2 != 0) {
            oddCount++;
        }
    }

    return oddCount <= 1 || coolDown(counts, k);
}

private boolean coolDown(int[] counts, int k) {
    for (int i = k / 2 + 1; i <= k; i++) {
        if (counts[i] % 2 != 0) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    // HashMap to store the occurrences modulo k of each element
    HashMap<Integer, Integer> modMap = new HashMap<>();

    // Iterate through the array elements
    for (int num : arr) {
        int remainder = num % k;
        // If the remainder is 0, increment by 1 for all numbers ending in 0
        if (remainder == 0) {
            modMap.put(0, modMap.getOrDefault(0, 0) + 1);
        } else {
            // If the remainder is not 0, check if the difference with k is already in the map
            if (modMap.containsKey(k - remainder)) {
                // If true, decrement the occurrences
                modMap.put(remainder, modMap.getOrDefault(remainder, 0) - 1);
                // Check if the decremented count is zero
                if (modMap.get(remainder) == 0) {
                    return false;
                }
            } else {
                // If false, add the remainder to the map
                modMap.put(remainder, modMap.getOrDefault(remainder, 0) + 1);
            }
        }
    }

    // If all checks pass, it is possible to divide the array
    return true;
}

