    for (int[] edge : edges) {
        adj.get(edge[0]).add(edge[1]);
        adj.get(edge[1]).add(edge[0]);
    }

    // Depth-First Search (DFS) function to calculate the time to collect all apples
    return dfs(0, 0, adj, hasApple);
