private int dfs(int node, int time, List<List<Integer>> adj, boolean[] hasApple) {
    if (time == 0) {
        return 1; // Return 1 to start counting from node 0
    }

    int minTime = 0;

    // Explore all neighboring nodes
    for (int neighbor : adj.get(node)) {
        if (neighbor != time) {
            int digTime = dfs(neighbor, time + 1, adj, hasApple);
            minTime += digTime;
            if (digTime > 0) {
                // If the neighboring node contains an apple, add the current node and 2 as time
                minTime += 2;
            }
        }
    }

    return minTime;
}

public String sortString(String s) {
        StringBuilder sb = new StringBuilder();
        char[] chars = s.toCharArray();
        Arrays.sort(chars);
        int left = 0, right = chars.length - 1;

        while (left <= right) {
            if (left == right) {
                sb.append(chars[left]);
                break;
            }
            sb.append(chars[left++]);
            sb.append(chars[right--]);
        }

        return sb.toString();
    }

