    while (count > 0) {
        // Add the smallest character from the minHeap
        if (!minHeap.isEmpty()) {
            char smallest = minHeap.poll();
            sortedString.append(smallest);
            count--;
        }

        // Add the largest character from the maxHeap
        if (!maxHeap.isEmpty()) {
            char largest = maxHeap.poll();
            sortedString.append(largest);
            count--;
        }
    }

    return sortedString.toString();
}

public String sortString(String s) {
    StringBuilder sb = new StringBuilder();
    char[] chars = s.toCharArray();
    Arrays.sort(chars);

    int i = 0, j = chars.length - 1;
    while (i <= j) {
        if (i == j) {
            sb.append(chars[i]);
            break;
        }
        sb.append(chars[i++]);
        sb.append(chars[j--]);
    }

    return sb.toString();
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    PriorityQueue<Character> minHeap = new PriorityQueue<>();
    PriorityQueue<Character> maxHeap = new PriorityQueue<>((a, b) -> b - a);

    for (int i = 0; i < s.length(); i++) {
        minHeap.offer(s.charAt(i));
        maxHeap.offer(s.charAt(i));
    }

    while (!minHeap.isEmpty() || !maxHeap.isEmpty()) {
        if (!minHeap.isEmpty()) {
            result.append(minHeap.poll());
            if (minHeap.isEmpty()) {
                if (!maxHeap.isEmpty()) {
                    result.append(maxHeap.poll());
                }
            } else {
                if (minHeap.peek() == maxHeap.peek()) {
                    result.append(minHeap.poll());
                }
            }
        }
        if (!maxHeap.isEmpty()) {
            result.append(maxHeap.poll());
            if (maxHeap.isEmpty()) {
                if (!minHeap.isEmpty()) {
                    result.append(minHeap.poll());
                }
            } else {
                if (minHeap.peek() == maxHeap.peek()) {
                    result.append(minHeap.poll());
                }
            }
        }
    }

    return result.toString();
}

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars); // Sort the characters in ascending order
    int left = 0, right = chars.length - 1;
    StringBuilder result = new StringBuilder();

    while (left <= right) {
        if (left == right) {
            result.append(chars[left]);
            break;
        }
        result.append(chars[left++]);
        result.append(chars[right--]);
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) return false;

    int totalSum = 0;
    int n = nums.length;
    int threshold = 0;

    // Calculate the total sum of the array
    for (int num : nums) {
        totalSum += num;
    }

    // Calculate the threshold (average of the array)
    threshold = totalSum / n;

    // Check if it's possible to split the array
    for (int i = 1; i < n; i++) {
        if (nums[0] == threshold && (nums[i] == 0 || nums[i] + nums[i - 1] == threshold)) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    int target = totalSum / 2;

    if (totalSum % 2 != 0) {
        return false;
    }

    int length = nums.length;
    long leftSum = 0;
    HashSet<Long> rightSums = new HashSet<>();

    for (int i = 0; i < length; i++) {
        leftSum += nums[i];
        if (leftSum == target) {
            return true;
        }
        rightSums.add(target - leftSum);
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int totalSum = Arrays.stream(nums).sum();
    if (totalSum % 2 != 0) return false;

    int targetSum = totalSum / 2;
    int[] prefixSum = new int[nums.length + 1];
    prefixSum[0] = 0;
    for (int i = 1; i <= nums.length; i++) {
        prefixSum[i] = prefixSum[i - 1] + nums[i - 1];
    }

    for (int i = 1; i < prefixSum.length; i++) {
        if (prefixSum[i] == targetSum) return true;

        if (prefixSum[i] - targetSum >= 0 && prefixSum[prefixSum.length - 1] - prefixSum[i] >= targetSum) {
            int leftSum = prefixSum[i] - targetSum;
            int remainingSum = prefixSum[prefixSum.length - 1] - leftSum;
            int[][] subarrays = splitArray(leftSum, remainingSum, i - 1);
            if (subarrays != null) return true;
        }
    }

    return false;
}

private int[][] splitArray(int leftSum, int remainingSum, int index) {
    if (leftSum < 0 || remainingSum < 0 || index < 0) {
        return null;
    }

    if (index == -1 && remainingSum == 0 && leftSum == 0) {
        return new int[][]{{}};
    }

    if (index > 0) {
        int[][] result = splitArray(leftSum, remainingSum, index - 1);
        if (result != null) {
            return result;
        }
    }

    if (index < nums.length - 1) {
        int[][] result = splitArray(leftSum + nums[index], remainingSum - nums[index], index + 1);
        if (result != null) {
            for (int[] subarray : result) {
                int[] newSubarray = IntArrays.merge(subarray, new int[]{nums[index]});
                result = addSubarray(result, newSubarray);
            }
            return result;
        }
    }

    return null;
}

private int[][] addSubarray(int[][] result, int[] subarray) {
    int[][] finalResult = new int[result.length + 1][subarray.length + 1];
    System.arraycopy(result, 0, finalResult, 0, result.length);
    finalResult[result.length] = subarray;
    return finalResult;
}

public boolean splitArraySameAverage(int[] nums) {
        int totalSum = Arrays.stream(nums).sum();
        int n = nums.length;
        double targetSum = totalSum / 2.0;

        for (int i = 1; i < n; i++) {
            if (nums[i] + nums[0] == 2 * targetSum && nums[0] != 0) {
                return true;
            }
        }
        return false;
    }

public boolean splitArraySameAverage(int[] nums) {
    int totalSum = Arrays.stream(nums).sum();
    if (totalSum % 2 != 0) {
        return false;
    }
    int avgSum = totalSum / 2;

    // HashMap to store the prefix sum and its index
    Map<Integer, Integer> prefixSumIndexMap = new HashMap<>();
    prefixSumIndexMap.put(0, -1);

    int currentSum = 0;
    for (int i = 0; i < nums.length; i++) {
        currentSum += nums[i];
        // Check if the current prefix sum minus the average sum has been seen elsewhere
        if (prefixSumIndexMap.containsKey(currentSum - avgSum)) {
            return true;
        }
        // Store the current prefix sum with its index in the map
        prefixSumIndexMap.put(currentSum, i);
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);

    int[] dp = new int[n + 1];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i - 1];
    }

    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];

    int prev1 = cost[0];
    int prev2 = cost[1];
    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(prev1, prev2);
        prev1 = prev2;
        prev2 = current;
    }
    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
        if (cost.length == 0) return 0;
        if (cost.length == 1) return cost[0];
        if (cost.length == 2) return Math.min(cost[0], cost[1]);

        int[] dp = new int[cost.length];
        dp[0] = cost[0];
        dp[1] = cost[1];

        for (int i = 2; i < cost.length; i++) {
            dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
        }

        return Math.min(dp[cost.length - 1], dp[cost.length - 2]);
    }

