public boolean hasAllCodes(String s, int k) {
        if (s.length() < k) return false;

        Set<String> seen = new HashSet<>();
        for (int i = 0; i <= s.length() - k; i++) {
            String subStr = s.substring(i, i + k);
            if (!seen.add(subStr)) return false;
        }

        return seen.size() == 1 << k;
    }

public boolean hasAllCodes(String s, int k) {
        Set<String> seenCodes = new HashSet<>();
        for (int i = 0; i <= s.length() - k; i++) {
            String code = s.substring(i, i + k);
            if (!seenCodes.add(code)) {
                return false;
            }
        }
        return true;
    }

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) return false;
    Set<String> seen = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        String substring = s.substring(i, i + k);
        if (seen.contains(substring)) return false;
        seen.add(substring);
    }
    return seen.size() == Math.pow(2, k);
}

public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    int m = (int) Math.pow(2, k);
    boolean[] present = new boolean[m];
    for (int i = 0; i < n; i++) {
        if (i + k > n) break;
        int value = 0;
        for (int j = i; j < i + k; j++) {
            value = (value << 1) | s.charAt(j) - '0';
        }
        if (!present[value]) {
            present[value] = true;
        } else {
            return false;
        }
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    int requiredStrings = (1 << k);
    boolean[] dp = new boolean[requiredStrings];

    // Initialize the dp array for the first string
    for (int i = 0; i < k; i++) {
        dp[i] = s.charAt(i) == '1';
    }

    // Fill the dp array for the rest of the string
    for (int i = k; i < n; i++) {
        int clearBit = (1 << (i - k));
        int addBit = (1 << i);
        dp[addBit] = dp[clearBit];
    }

    // Check if all bits are set to true
    return (dp[requiredStrings - 1]);
}

