static int minInsertions(String s) {
    int balance = 0, insertionsNeeded = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            balance++;
        } else if (s.charAt(i) == ')' && balance <= 0) {
            insertionsNeeded++;
            balance++;
        } else {
            balance--;
        }
    }

    // Additional insertions needed to balance the rest of the string
    insertionsNeeded += balance;

    return insertionsNeeded;
}

