public int minInsertions(String s) {
        Stack<Character> stack = new Stack<>();
        int balance = 0;
        int insertions = 0;

        for (char c : s.toCharArray()) {
            if (c == '(') {
                stack.push(c);
            } else {
                if (stack.isEmpty()) {
                    balance++;
                    insertions++;
                } else {
                    stack.pop();
                }
            }
        }

        int missingLeft = balance;
        insertions += missingLeft;

        return insertions;
    }

public int minOperations(int n) {
    if (n == 1) return 0;
    int left = 0, right = n - 1;
    int operations = 0;
    while (left < right) {
        operations += right - left - 1;
        left++;
        right--;
    }
    return operations;
}

public int minOperations(int n) {
    int left = 0;
    int right = n - 1;
    int operations = 0;

    while (left < right) {
        int x = 2 * left + 1;
        int y = 2 * right + 1;
        if (x == y) {
            operations += (y - x) / 2;
            break;
        } else if (x < y) {
            operations += (y - x) / 2;
            left++;
            right--;
        } else {
            operations += (y - x) / 2;
            right--;
        }
    }

    return operations;
}

