    int minVal = n % 2 == 0 ? n : n - 1;
    int operations = 0;

    // For each element in the array, calculate the operation required to make it equal to the minVal
    for (int i = 0; i < n; i++) {
        int currentVal = 2 * i + 1;
        operations += Math.abs(currentVal - minVal);
    }

    return operations;
}

public int minOperations(int n) {
    int low = 1;
    int high = n;
    int count = 0;

    while (low < high) {
        count += (high - low) / 2;
        if ((2 * low + 1) + (2 * high + 1) == n) {
            low++;
            high--;
        } else if ((2 * low + 1) + (2 * high + 1) < n) {
            low++;
        } else {
            high -= 2;
        }
    }

    return count + ((n - 1) / 2);
}

