    int minSum = 0;
    int maxResult = 0;

    for(int i = 0; i < nums.length; i++){
        maxSum = Math.max(nums[i], maxSum + nums[i]);
        minSum = Math.min(nums[i], minSum + nums[i]);
        maxResult = Math.max(maxResult, Math.max(maxSum, -minSum));
    }
    return maxResult;
}

public int maxAbsoluteSum(int[] nums) {
    int max = Integer.MIN_VALUE;
    int min = Integer.MAX_VALUE;

    for (int num : nums) {
        if (num > max) {
            max = num;
        } else if (num < min) {
            min = num;
        }
    }

    int absMaxSum = Math.max(max, -min);
    return absMaxSum;
}

public int findMinFibonacciNumbers(int k) {
        int[] fibSequence = {0, 1};
        int fibIndex = 0;
        int sequenceSum = 0;

        // Generate Fibonacci sequence up to a point where the next number is equal to or greater than k
        while (true) {
            int nextFib = fibSequence[fibIndex] + fibSequence[fibIndex + 1];
            if (nextFib >= k) {
                break;
            } else {
                fibSequence[fibIndex + 1] = nextFib;
                fibIndex++;
            }
        }

        int count = 0;
        for (int i = fibSequence.length - 1; i >= 0; i--) {
            while (sequenceSum + fibSequence[i] <= k) {
                count++;
                sequenceSum += fibSequence[i];
            }
        }

        return count;
    }

public int findMinFibonacciNumbers(int k) {
    // Initialize an array to store Fibonacci numbers up to k
    int[] fibonacci = new int[k + 1];
    fibonacci[1] = 1;
    fibonacci[2] = 1;

    // Generate Fibonacci numbers up to k
    for (int i = 3; i <= k; i++) {
        fibonacci[i] = fibonacci[i - 1] + fibonacci[i - 2];
    }

    // Initialize the result variable
    int count = 0;

    // Use a greedy approach to find the minimum number of Fibonacci numbers
    for (int i = fibonacci.length - 1; i >= 0; i--) {
        while (k >= fibonacci[i]) {
            k -= fibonacci[i];
            count++;
        }
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
    int[] fibs = generateFibonacciNumbers();
    Map<Integer, Integer> memo = new HashMap<>();
    return minFibonacciNumbersRecursive(k, fibs, memo);
}

private int minFibonacciNumbersRecursive(int target, int[] fibs, Map<Integer, Integer> memo) {
    if (target == 0)
        return 0;
    if (target < 0)
        return Integer.MAX_VALUE;

    if (memo.containsKey(target))
        return memo.get(target);

    int minFib = Integer.MAX_VALUE;
    for (int fib : fibs) {
        if ( fib <= target) {
            minFib = Math.min(minFib, minFibonacciNumbersRecursive(target - fib, fibs, memo) + 1);
        }
    }

    memo.put(target, minFib);
    return memo.get(target);
}

private int[] generateFibonacciNumbers() {
    int[] fibs = new int[100];
    fibs[0] = 1;
    fibs[1] = 1;
    int index = 2;
    while (fibs[index - 1] + fibs[index - 2] <= 10000) {
        fibs[index] = fibs[index - 1] + fibs[index - 2];
        index++;
    }
    return fibs;
}

public int findMinFibonacciNumbers(int k) {
