}

private int recurse(List<Integer> list, int k) {
    if (k < 0) return (int)1e9;
    if (k == 0) return 0;

    int result = Integer.MAX_VALUE;
    for (Integer val : list) {
        int temp = recurse(list, k - val);
        if (temp != (int) 1e9) {
            result = Math.min(result, 1 + temp);
        }
    }
    return result;
}

public int findMinFibonacciNumbers(int k) {
    // Base case for Fibonacci sequence
    int[] fibonacci = new int[k + 1];
    fibonacci[0] = 0;
    fibonacci[1] = 1;

    // Generate Fibonacci sequence
    for (int i = 2; i <= k; i++) {
        fibonacci[i] = fibonacci[i - 1] + fibonacci[i - 2];
    }

    // Find the minimum number of Fibonacci numbers
    int count = 0;
    for (int i = fibonacci.length - 1; i >= 0; i--) {
        while (k >= fibonacci[i]) {
            k -= fibonacci[i];
            count++;
        }
        if (k == 0) {
            return count;
        }
    }

    return count;
}

