public String makeGood(String s) {
    int l = s.length();
    Stack<Character> stack = new Stack<>();
    for (int i = 0; i < l; i++) {
        if (!stack.isEmpty() && Math.abs(stack.peek() - s.charAt(i)) == 32) {
            stack.pop();
        } else {
            stack.push(s.charAt(i));
        }
    }
    return new String(stack);
}

public String makeGood(String s) {
    while (true) {
        int left = 0;
        int right = 1;
        boolean found = false;
        while (right < s.length()) {
            if (Math.abs(s.charAt(left) - s.charAt(right)) == 32) {
                s = s.substring(0, left) + s.substring(right + 1);
                found = true;
                break;
            }
            left++;
            right++;
        }
        if (!found) break;
    }
    return s;
}

