public int maxUniqueSplit(String s) {
    if (s == null || s.length() < 1) {
        return 0;
    }

    int maxSplit = 0;
    int start = 0;
    Map<String, Integer> characterCounts = new HashMap<>();

    for (int i = 0; i < s.length(); i++) {
        String current = s.substring(start, i + 1);
        if (!characterCounts.containsKey(current)) {
            characterCounts.put(current, 0);
            maxSplit++;
        }
        characterCounts.put(current, characterCounts.get(current) + 1);
    }

    return maxSplit;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }

    int maxSplit = 0;
    Set<Character> seen = new HashSet<>();
    for (int i = 0; i < s.length(); i++) {
        if (seen.contains(s.charAt(i))) {
            // Reset the seen set and try again starting from index i+1
            seen.clear();
            i++;
        } else {
            seen.add(s.charAt(i));
            maxSplit++;
        }
    }

    return maxSplit;
}

public int maxUniqueSplit(String s) {
    int count = 0;
    int prefixSum = 0;
    int left = 0;
    Set<Integer> prefix_set = new HashSet<>();

    for (int right = 0; right < s.length(); right++) {
        prefix_set.add(prefixSum);
        prefixSum += s.charAt(right) - 'a';
        while (prefix_set.contains(prefixSum)) {
            prefix_sum -= s.charAt(left) - 'a';
            left++;
        }
        count++;
    }
    return count;
}

public int maxUniqueSplit(String s) {
        if (s == null || s.length() < 1) {
            return 0;
        }

        int maxLength = 0;
        int maxLengthUniqueSubstrings = 0;
        Set<String> uniqueSubstrings = new HashSet<>();

        for (int i = 0; i < s.length(); i++) {
            String current = s.substring(i);
            if (!uniqueSubstrings.contains(current)) {
                uniqueSubstrings.add(current);
                maxLengthUniqueSubstrings++;
                maxLength = Math.max(maxLength, maxLengthUniqueSubstrings);
            }
        }

        return maxLength;
    }

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) return 0;

    return maxUniqueSplit(s, 0, new HashSet<>(), 0);
}

private int maxUniqueSplit(String s, int index, Set<String> used, int length) {
    if (index == s.length() && length > 0) {
        return length;
    }

    int maxUnique = 0;
    for (int i = index; i < s.length(); i++) {
        String candidate = s.substring(index, i + 1);
        if (!used.contains(candidate)) {
            used.add(candidate);
            maxUnique = Math.max(maxUnique, maxUniqueSplit(s, i + 1, used, length + 1));
            used.remove(candidate);
        }
    }

    return maxUnique;
}

