public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder();
    while (k > 0 && n > 0) {
        int remainder = k % 26;
        sb.insert(0, (char) ('a' + remainder - 1));
        k = k / 26;
        n--;
    }
    return sb.toString();
}

public String getSmallestString(int n, int k) {
    StringBuffer sb = new StringBuffer();
    while (k > 0) {
        if (k % 26 == 0) {
            sb.append('a');
            k -= 26;
        } else {
            sb.append((char) ('a' + k % 26 - 1));
            k -= k % 26;
        }
    }
    return sb.reverse().toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder smallest = new StringBuilder();
    for (int i = 97; i < 123; i++) {
        while (k > 0 && --i >= 97) {
            if (k >= i) {
                smallest.append((char) i);
                k -= i;
                break;
            }
        }
        if (k > 0) {
            return smallest.toString();
        }
    }
    return smallest.toString();
}

public String getSmallestString(int n, int k) {
    if (n == 0 || k == 0) {
        return "";
    }
    int[] freq = new int[26];
    int total = 0;

    for (int i = n - 1; i >= 0; i--) {
        total += i;
        freq[i] = (total + k - 1) / (i + 1);
        k -= (freq[i] * (i + 1));
    }

    StringBuilder result = new StringBuilder(n);
    for (int i = n - 1; i >= 0; i--) {
        result.append((char) ('a' + (freq[i] - 1)));
    }

    return result.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int modulus = k % 26;
    int quotient = k / 26;

    for (int i = 0; i < n; i++) {
        int value = (i < quotient) ? modulus : modulus + 1;
        char c = (char) ('a' + value - 26);
        result.append(c);
    }

    return result.toString();
}

public static double calculateProbability(int n) {
    if (n <= 1) {
        return 1.0;
    }
    if (n == 2) {
        return 0.5;
    }
    // Base case for n = 3
    if (n == 3) {
        return 0.5;
    }
    // Reduce the problem to the subproblem
    return 1.0 - 1.0 / calculateProbability(n - 1);
}

public static double calculateProbability(int n) {
