    if (n == 1) {
        return 1.0; // If there is only one passenger, the probability is 1 (first Passenger will sit in their own seat)
    } else {
        // Probability that the second passenger will not sit in the first passenger's seat
        double result = (n - 1) / (double) n * calculateProbability(n - 1);
        return result;
    }
}

