        throw new IllegalArgumentException("Input array must not be null or empty");
    }

    int ones = 0, twos = 0;

    // Iterate through each number in the array
    for (int num : nums) {
        ones = (ones ^ num) & ~twos; // Update ones
        twos = (twos ^ num) & ~ones; // Update twos
    }

    return ones;
}

