public static List<Integer> findSteppingNumbers(int low, int high) {
        boolean[] visited = new boolean[high + 1];
        ArrayList<Integer> steppingNumbers = new ArrayList<>();
        visited[0] = true;

        int last_digit = high;
        while (last_digit >= 1) {
            int digit = last_digit - 1;
            if (digit > 0) {
                if (!visited[digit]) {
                    steppingNumbers.add(digit);
                    visited[digit] = true;
                }
            }

            digit = last_digit + 1;
            if (digit <= high && !visited[digit]) {
                steppingNumbers.add(digit);
                visited[digit] = true;
            }

            last_digit--;
        }

        // Sort the array in ascending order
        steppingNumbers.sort(null);

        // Check if the first step bound is within the range
        if (steppingNumbers.size() == 0 || steppingNumbers.get(0) < low) {
            steppingNumbers.clear();
        }

        // Check if the last step bound is within the range
        if (steppingNumbers.size() > 0 && steppingNumbers.get(steppingNumbers.size() - 1) > high) {
            steppingNumbers.clear();
        }

        return steppingNumbers;
    }

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low >= minStepNumber(low) && high <= maxStepNumber(high)) { // ensure high is within the stepping range
        for (int i = low; i <= high; i++) {
            if (isSteppingNumber(i)) {
                result.add(i);
            }
        }
    }  
    result.sort(Integer::compare); // sort the list in ascending order
    return result;
}

private static int minStepNumber(int num) {
    if (num == 0) return 1; // 0 is not a stepping number
    int minNum = num;
    num /= 10;
    while (num > 0) {
        if (num % 2 == 1) return -1; // stepping numbers cannot have odd digits in the last position
        if (num % 5 == 1) return -1; // stepping numbers cannot have 5 as the last digit
        if (num % 10 == 4 || num % 10 == 6) return -1; // stepping numbers cannot have 4 or 6 as the last digit
        num /= 10;
    }
    while (minNum % 2 == 1) minNum /= 10; // remove the last digit that is odd
    while (minNum % 5 == 1) minNum /= 10; // remove the last digit that is 5
    while (minNum % 10 == 4 || minNum % 10 == 6) minNum /= 10; // remove the last digit that is 4 or 6
    return minNum;
}

private static int maxStepNumber(int num) {
    int maxNum = num;
    int temp = num;
    while (temp > 0) {
        temp /= 10;
    }
    while (maxNum % 2 == 1) maxNum *= 10; // add the last digit that is odd
    while (maxNum % 5 == 1) maxNum *= 10; // add the last digit that is 5
    while (maxNum % 10 == 4 || maxNum % 10 == 6) maxNum *= 10; // add the last digit that is 4 or 6
    return maxNum;
}

private static boolean isSteppingNumber(int num) {
    int prev = -1;
    while (num > 0) {
        int curr = num % 10;
        if (curr > prev + 1 || curr < prev - 1) return false;
        prev = curr;
        num /= 10;
    }
    return true;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    for (int num = low; num <= high; num++) {
        if (checkStepping(num)) {
            result.add(num);
        }
    }
    result.sort(Integer::compare);
    return result;
}

private static boolean checkStepping(int num) {
    if (num < 0) {
        return false;
    }

    String numStr = String.valueOf(num);
    for (int i = 1; i < numStr.length(); i++) {
        int diff = Integer.parseInt(String.valueOf(numStr.charAt(i - 1))) - Integer.parseInt(String.valueOf(numStr.charAt(i)));
        if (diff != 1 || diff != -1) {
            return false;
        }
    }
    return true;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
        Set<Integer> steppingNumbers = new LinkedHashSet<>();
        Stack<Integer> queue = new ArrayDeque<>();

        queue.push(0);
        while (!queue.isEmpty()) {
            int num = queue.poll();
            if (num >= low && num <= high) {
                steppingNumbers.add(num);
            }
            if (num < high) {
                processDigit(queue, num, 1, low, high);
                processDigit(queue, num, -1, low, high);
            }
        }

        List<Integer> sortedNumbers = new ArrayList<>(steppingNumbers);
        sortedNumbers.sort(Integer::compareTo);
        return sortedNumbers;
    }

private static void processDigit(Stack<Integer> queue, int num, int direction, int low, int high) {
        int lastDigit = num % 10;
        int newDigit = lastDigit + direction;
        if (newDigit >= 0 && newDigit <= 9 &&
            newDigit >= lastDigit || newDigit + 9 <= lastDigit || newDigit - 9 >= lastDigit) {
            if (newDigit == low) {
                queue.push(num * 10 + newDigit);
            } else if (newDigit == high) {
                queue.addAll(Arrays.asList(num * 10 + newDigit, num * 10 + newDigit - 1, num * 10 + newDigit + 1));
            } else {
                queue.add(num * 10 + newDigit);
            }
        }
    }

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();

    for (int num = low; num <= high; num++) {
        if (isSteppingNumber(num)) {
            result.add(num);
        }
    }

    Collections.sort(result);
    return result;
}

private static boolean isSteppingNumber(int num) {
    if (num < 0 || num > 9) {
        return false;
    }
    int lastDigit = num % 10;
    for (int i = 0; i < num; i++) {
        int nextDigit = i % 10;
        if (Math.abs(lastDigit - nextDigit) != 1) {
            return false;
        }
    }
    return true;
}

public static int countDigitOne(int n) {
