    return count;
}

private static int streak(int num) {
    if (num == 0) {
        return 0;
    }
    int factor = 1;
    int digit = num % 10;
    int total = 0;
    while (num != 0) {
        int withoutCurrentDigit = num / 10;
        total += (withoutCurrentDigit + 1) * factor;
        num /= 10;
        digit *= 10;
        factor *= 10;
    }
    return total + (digit == 1 ? 1 : 0);
}

