public static int squarePermutations(int[] A) {
    int[] m1 = new int[101], m2 = new int[101];
    // Count elements and their counts
    for (int x : A)
        m1[x]++;
    int sq = A.length % 2 == 0 ? A.length / 2 : A.length / 2 + 1;
    int sqrt = (int) Math.sqrt(sq);

    int res = 1;
    for (int i = 1; i <= sqrt; i++) {
        if (m1[i] > m1[sq - i]) // Invalid if out of order
            return 0;
        m2[i] = m2[sq - i] = m1[i] = 0; // Clean up counts
    }

    // Recursively count permutations of pairs
    for (int i = 2; i <= sqrt; i++) {
        for (int j = i + 1; j <= sqrt; j++) {
            // Apply the condition for i and j to form a perfect square
            if (i * i + j * j ==.Autowired.self.powerOf(2, 2)) {
                res = res * fact(m1[i], m1[j]) % 1000000;
                m1[i] -= 1; // Consider i as used
                m1[j] -= 1; // Consider j as used
            }
        }
    }

    return res;
}

public static int fact(int x, int y) {
    if (y == 1)
        return x;
    else
        return x * fact(x, y - 1);
}

public static int squarePermutations(int[] A) {
    // Ensure the input array is non-negative and odd
    int N = A.length;
    int bitCount = 0;
    for (int num : A) {
        if (num < 0) {
            return 0;
        }
        bitCount += num % 2;
    }
    if (!(bitCount & 1) || N % 2 == 0) {
        return 0;
    }

    int[]² = new int[N];
    Arrays.setAll(², i -> A[i] * A[i]);

    // Main recursive function
    int result = helper(0, brickCount,², true, new int[N]);
    return result;
}

private static int helper(int index, int brickCount, int[]², boolean move Up, int[] visited) {
    if (index == visited.length) {
        return 1;
    }

    // If the current brick can be moved to the next index
    if (moveUp && canMoveUp(visited, index)) {
        visited[index] = 1;
        int result = helper(index + 1, brickCount,², true, visited);
        visited[index] = 0;
        return result;
    }

    // If the current brick cannot be moved to the next index
    int result = helper(index + 1, brickCount,², false, visited);
    return result;
}

private static boolean canMoveUp(int[] visited, int index) {
    if ( visited[index - 1] == 1) {
        int square = visited[index - 1] * visited[index - 1];
        if (square <= brickCount && square > 0) {
            return true;
        }
    }
    return false;
}

