public static int squarePermutations(int[] A) {
    int count = 0;
    int n = A.length;
    findDistinctPermutations(A, 0, n - 1, count, new boolean[n]);
    return count;
}

private void findDistinctPermutations(int[] A, int left, int right, int count, boolean[] used) {
    if (left >= right) {
        if (calculateSumOfAllPairs() == 0) {
            count++;
        }
        return;
    }

    for (int i = left; i <= right; i++) {
        if (used[i]) continue;

        swap(A, left, i);
        used[i] = true;
        findDistinctPermutations(A, left + 1, right, count, used);
        used[i] = false;
        swap(A, left, i);
    }
}

private int calculateSumOfAllPairs() {
    int sum = 0;
    for (int i = 0; i < A.length - 1; i++) {
        sum += (A[i + 1] - A[i]) * (A[i + 1] - A[i]);
    }
    return sum;
}

private void swap(int[] A, int i, int j) {
    int temp = A[i];
    A[i] = A[j];
    A[j] = temp;
}

