public static int[] diagonalOrder(int[][] mat) {
    int rowLength = mat.length;
    int colLength = mat[0].length;
    List<Integer> diagonal = new ArrayList<>();

    for (int k = -Math.min(rowLength, colLength); k <= Math.max(rowLength, colLength); k++) {
        int curRow = 0;
        int curCol = 0;
        for (int i = 0; i < Math.abs(k); i++) {
            if (k >= 0) {
                curRow++;
                curCol++;
            } else {
                curRow--;
                curCol--;
            }
        }

        while (curRow < rowLength && curCol < colLength) {
            diagonal.add(mat[curRow][curCol]);
            curRow++;
            curCol++;
        }
    }

    return diagonal.stream().mapToInt(i -> i).toArray();
}

public static int[] diagonalOrder(int[][] mat) {
    int rows = mat.length;
    if(rows == 0) {
        return new int[0];
    }
    int cols = mat[0].length;
    if(cols == 0) {
        return new int[0];
    }

    int left_boundary = 0;
    int right_boundary = cols - 1;
    int top_boundary = 0;
    int bottom_boundary = rows - 1;
    int direction = 1; // 1 indicates North-West direction, -1 indicates South-East direction

    int[] result = new int[rows * cols];
    int index = 0;

    while(left_boundary <= right_boundary && top_boundary <= bottom_boundary) {
        for(int i = left_boundary; i <= right_boundary && i <= bottom_boundary; i++) {
            if(direction == 1) {
                result[index++] = mat[i][left_boundary];
            } else {
                result[index++] = mat[i][right_boundary];
            }
        }

        left_boundary++;
        if(right_boundary > left_boundary) {
            right_boundary--;
        }
        top_boundary++;
        if(bottom_boundary > top_boundary) {
            bottom_boundary--;
        }
        direction = -direction;
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
