        if (row == col) {
            // Move diagonally downwards
            if (row == mat.length - 1 || col == mat[0].length - 1) {
                break;
            }
            row++;
            col++;
        } else if (col == mat[0].length - 1) {
            // Move diagonally towards the left
            if (row == mat.length - 1) {
                break;
            }
            row++;
        } else if (row == mat.length - 1) {
            // Move diagonally towards the up
            if (col == 0) {
                break;
            }
            row--;
            col--;
        } else {
            // Move diagonally to the left and upwards
            row--;
            col++;
        }
    }

    int[] resultArray = new int[result.size()];
    for (int i = 0; i < result.size(); i++) {
        resultArray[i] = result.get(i);
    }

    return resultArray;
}

