                // This means the number is already in ascending order
                return false;
            }
        }

        return false;
    }

public static int findSmallestInteger(int n) {
        // Convert the number to a character array
        char[] digits = Integer.toString(n).toCharArray();
        int len = digits.length;

        // Create a copy of the digits array
        char[] arr = Arrays.copyOf(digits, len);

        // Sort the array in ascending order
        Arrays.sort(arr);

        // Iterate through the sorted array from the end
        for (int i = len - 2; i >= 0; i--) {
            if (arr[i] < arr[i + 1]) {
                // Find the smallest digit greater than arr[i]
                int j = len - 1;
                while (j > i && arr[j] >= arr[i]) {
                    j--;
                }

                // Swap the found digit and the current digit
                char temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;

                // Reverse the digits from index i+1 to the end
                Arrays.sort(arr, i + 1, len);

                // Convert the sorted array back to an integer and return it
                return Integer.parseInt(new String(arr));
            }
        }

        // Return -1 if no such integer is found
        return -1;
    }

public static int findSmallestInteger(int n) {
