    for (int i = len - 2; i >= 0; i--) {
        for (int j = i + 1; j < len; j++) {
            if (numStr.charAt(i) > numStr.charAt(j)) {
                Collections.swap(numStr, i, j);
                Collections.sort(numStr.subList(i + 1, len));
                return Integer.parseInt(numStr);
            }
        }
    }

    return -1; // If no such arrangement exists
}

public int findSmallestInteger(int n) {
    List<Integer> digits = new ArrayList<>();
    boolean isDesc = true;
    Set<Integer> used = new HashSet<>();

    // Convert the number n to a list of its digits
    while (n > 0) {
        digits.add(n % 10);
        n /= 10;
    }

    // Check if the number has any repeating digits
    for (int i = 0; i < digits.size() - 1; i++) {
        if (digits.get(i) == digits.get(i + 1)) {
            isDesc = false;
            break;
        }
    }

    if (isDesc) {
        return -1; // No rearrangement can be done
    }

    int result = 0;
    List<Integer> nonRepeatingDigits = new ArrayList<>();

    // Filter out the repeating digits and sort them
    for (int digit : digits) {
        if (!used.contains(digit)) {
            nonRepeatingDigits.add(digit);
            used.add(digit);
        }
    }

    Collections.sort(nonRepeatingDigits, Collections.reverseOrder());

    // Build the smallest number using the remaining numbers
    for (int i = 0; i < digits.size(); i++) {
        if (i < nonRepeatingDigits.size()) {
            result *= 10;
            result += nonRepeatingDigits.get(i);
        } else {
            result *= 10;
            result += digits.get(i);
        }
    }

    return result;
}

