    }

    if (n == 1) {
        return 1;
    }

    PriorityQueue<Integer> minHeap = new PriorityQueue<>();
    minHeap.offer(1);

    Set<Integer> seen = new HashSet<>();
    seen.add(1);

    int[] factors = {2, 3, 5};

    for (int i = 1; i < n; i++) {
        int min = minHeap.poll();
        if (min * 2 > min && !seen.contains(min * 2)) {
            minHeap.offer(min * 2);
            seen.add(min * 2);
        }
        if (min * 3 > min && !seen.contains(min * 3)) {
            minHeap.offer(min * 3);
            seen.add(min * 3);
        }
        if (min * 5 > min && !seen.contains(min * 5)) {
            minHeap.offer(min * 5);
            seen.add(min * 5);
        }
        minHeap.offer(min);
    }

    return minHeap.peek();
}

