    for (int i = 1; i < n - 1; i++) {
        if (s.charAt(i) != s.charAt(i - 1) && s.charAt(i) != s.charAt(i + 1)) {
            maxEnergy += 1;
        }
    }

    // Check the last character
    if (n >= 2 && s.charAt(n - 2) == s.charAt(n - 1)) {
