    for (int i = 0; i < s.length(); i++) {
        // Track the total count of the current character
        int count = 1;

        for (int j = i + 1; j < s.length(); j++) {
            // If the current characters are the same, increment the count
            if (s.charAt(i) == s.charAt(j)) {
                count++;
            } else {
                // For the next iteration, reset the count
                break;
            }
        }

        // Update the maximum length if the current count is greater than the maximum length found so far
        maxLength = Math.max(maxLength, count);
    }

    return maxLength;
}

