    lexicalOrderUtil(n, 1, result);
    return result;
}

private static void lexicalOrderUtil(int n, int current, ArrayList<Integer> result) {
    if (current > n)
        return;
    result.add(current);
    // Go to next set of digits in lexicographical order
    if (current * 10 <= n)
        lexicalOrderUtil(n, current * 10, result); // Next digit in same set
    else
        // Orthodox trick: backtracking to current with replaced last digit and next biggest
        if (current != 9)
            lexicalOrderUtil(n, current + 1, result); // Next digit in next set
}

public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        List<Integer> current = new ArrayList<>();
        current.add(1);
        while (!current.isEmpty()) {
            for (int i = 0; i < current.size(); i++) {
                int num = current.remove(0);
                if (num <= n) {
                    result.add(num);
                    if (num * 10 <= n) {
                        current.add(num * 10);
                    }
                    if (num + 1 <= n) {
                        current.add(num + 1);
                    }
                }
            }
        }
        return result;
    }

