private static void dfs(List<Integer> result, int current, int n) {
        if (current * 10 > n) {
            return;
        }
        if (current != 0) {
            result.add(current * 10);
        }
        for (int i = 0; i <= 9; i++) {
            dfs(result, current * 10 + i, n);
        }
    }

public List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            result.add(i);
        }
        result.sort(null);
        return result;
    }

