public static int minPerfectSquareSum(int n) {
    if (n < 1) {
        return 0;
    }

    int[] dp = new int[n + 1];
    dp[1] = 1;

    for (int i = 2; i <= n; i++) {
        int minSum = Integer.MAX_VALUE;
        for (int j = 1; j <=Math.sqrt(i); j++) {
            minSum = Math.min(minSum, 1 + dp[i - j * j]);
        }
        dp[i] = minSum;
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 2) {
        return n;
    }
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
        // If n is less than or equal to 0, return 0 since it's not possible to form a sum
        if (n <= 0) {
            return 0;
        }

        // Array to store the minimum number of perfect squares needed for each number up to n
        int[] dp = new int[n + 1];
        dp[0] = 0; // Base case: 0 perfect squares are needed for the sum 0

        // Iterate through each number from 1 to n
        for (int i = 1; i <= n; i++) {
            // Initialize the minimum number of perfect squares needed for the current number
            dp[i] = i;

            // Check all numbers less than i to find the optimal formula
            for (int j = 1; j <= i; j++) {
                int square = j * j;
                if (square <= i) {
                    // Update the minimum number of perfect squares used
                    dp[i] = Math.min(dp[i], dp[i - square] + 1);
                }
            }
        }

        // Return the minimum number of perfect squares needed for the target number n
        return dp[n];
    }

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    // Base case: 0 perfect squares are needed for 0
    if (n <= 0) {
        return 0;
    }

    int result = n;

    // Factorize n and use the least number of perfect squares
    for (int i = 1; i * i <= n; i++) {
        int possiblePerfectSquare = i * i;
        if (possiblePerfectSquare <= n) {
            // Recursively solve for the remaining
            int remaining = n - possiblePerfectSquare;
            result = Math.min(result, 1 + minPerfectSquareSum(remaining));
        }
    }

    return result;
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    StringBuilder result = new StringBuilder();
    StringBuilder currentWord = new StringBuilder();

    for (char c : s.toCharArray()) {
        if (c == ' ') {
            // Reverse the current word and append it to the result
            result.append(currentWord.reverse()).append(" ");
            currentWord.setLength(0); // Reset current word for the next word
        } else {
            currentWord.append(c);
        }
    }

    // Append the last word after the last space
    result.append(currentWord.reverse());

    return result.toString();
}

public static String reverseWords(String s) {
        String[] words = s.split(" ");
        StringBuilder reversedSentence = new StringBuilder();

        for (String word : words) {
            StringBuilder reversedWord = new StringBuilder();
            for (int i = word.length() - 1; i >= 0; i--) {
                reversedWord.append(word.charAt(i));
            }
            reversedSentence.append(reversedWord.toString());
            reversedSentence.append(" ");
        }

        // Trim the last space and return the result
        return reversedSentence.toString().replaceAll("( )+", " ").trim();
    }

public static String reverseWords(String s) {
    if (s == null || s.length() <= 1) {
        return s;
    }

    StringBuilder result = new StringBuilder();
    String[] words = s.split("\\s+");
    for (String word : words) {
        char[] characters = word.toCharArray();
        for (int i = 0, j = characters.length - 1; i < j; i++, j--) {
            char temp = characters[i];
            characters[i] = characters[j];
            characters[j] = temp;
        }
        result.append(String.valueOf(characters));
        if (i < words.length - 1) {
            result.append(" ");
        }
    }

    return result.toString();
}

